{ 

  /* - To populate a default value into a newly required field: */
  "isPartialHour": $coalesce([field, false])
}

data.transform:
(
  /* Extract timezone */
  $timezone := $coalesce([$.setting.edges[0].node.defaultValue, $momentTzGuess()]);
  
  /* Calculate hour boundaries (previous hour) in local time */
  $nowLocal := $moment().tz($timezone);
  $hourStartLocal := $nowLocal.startOf('hour').subtract(1, 'hour');
  $hourEndLocal := $moment($hourStartLocal).add(1, 'hour');
  
  /* Format as ISO string to get UTC representation */
  $hourStartQuery := $hourStartLocal.toISOString();
  $hourEndQuery := $hourEndLocal.toISOString();
  $periodAt := $hourStartLocal.toISOString();
  $dayHour := $number($hourStartLocal.format('H'));
  
  /* Build workcenter → scheduleGroupId mapping */
  $workcenters := $.workcenter.edges.node;
  $workcenterScheduleGroup := $merge($workcenters.{
    id: scheduleGroupId
  });
  
  /* Get unique scheduleGroupIds */
  $scheduleGroupIds := $distinct($workcenters.scheduleGroupId)[$ != null];
  
  /* Build scheduleGroupId → schedule info mapping (with shift start) */
  $schedulesByGroup := $merge($scheduleGroupIds.(
    $groupId := $;
    $currentSchedules := $scheduleGroup($groupId).getCurrentSchedules(
      $hourStartLocal, 
      $hourEndLocal, 
      { "inclusive": true }
    );
    $activeSchedule := $currentSchedules[0];
    { 
      ($groupId): $activeSchedule ? {
        "scheduleId": $activeSchedule.scheduleId,
        "scheduleName": $activeSchedule.name,
        "isActive": true,
        "shiftStartAt": $activeSchedule.startAt,
        "shiftEndAt": $activeSchedule.endAt
      } : {
        "scheduleId": null,
        "scheduleName": "Unscheduled",
        "isActive": false,
        "shiftStartAt": null,
        "shiftEndAt": null
      }
    }
  ));
  
  /* Return combined config */
  {
    "boundaries": {
      "timezone": $timezone,
      "hourStartQuery": $hourStartQuery,
      "hourEndQuery": $hourEndQuery,
      "periodAt": $periodAt,
      "dayHour": $dayHour
    },
    "workcenterScheduleGroup": $workcenterScheduleGroup,
    "schedulesByGroup": $schedulesByGroup
  }
)

data.query:
query GetOeeConfig {
  setting(where: { id: { _eq: "TimeZone" } }) {
    edges {
      node {
        defaultValue
      }
    }
  }
  workcenter(where: { isActive: { _eq: true } }, first: 1000) {
    edges {
      node {
        id
        code
        name
        scheduleGroupId
      }
    }
  }
}

data.transform:
'use strict';

var oeeConfig = $state.context.oeeConfig;
var boundaries = oeeConfig.boundaries;

var hourStartQuery = boundaries.hourStartQuery;
var hourEndQuery = boundaries.hourEndQuery;
var hourStartMs = new Date(hourStartQuery).getTime();
var hourEndMs = new Date(hourEndQuery).getTime();
var dayHour = boundaries.dayHour;

var productionEdges = $.productionLog?.edges || [];
var historyEdges = $.workcenterHistory?.edges || [];
var existingOeeEdges = $.oeeHourly?.edges || [];

// ========================================
// ISO 22400 COMPLIANT HELPER FUNCTIONS
// ========================================

function calcOverlapMs(startMs1, endMs1, startMs2, endMs2) {
  var start = Math.max(startMs1, startMs2);
  var end = Math.min(endMs1, endMs2);
  return Math.max(0, end - start);
}

function calcShiftHour(shiftStartAt, periodStartAt) {
  if (!shiftStartAt || !periodStartAt) return 0;
  
  var shiftStartMs = new Date(shiftStartAt).getTime();
  var periodMs = new Date(periodStartAt).getTime();
  
  var hoursIntoShift = (periodMs - shiftStartMs) / (60 * 60 * 1000);
  return Math.max(1, Math.floor(hoursIntoShift) + 1);
}

// ========================================
// STEP 1: Group existing OEE periods by workcenter
// Include ALL periods with scheduleId
// ========================================
var oeePeriodsMap = {};

for (var i = 0; i < existingOeeEdges.length; i++) {
  var oeeNode = existingOeeEdges[i].node;
  var wcId = oeeNode.workcenterId;
  
  // ONLY process periods that have a scheduleId
  if (!oeeNode.scheduleId) {
    continue;
  }
  
  if (!oeePeriodsMap[wcId]) {
    oeePeriodsMap[wcId] = [];
  }
  
oeePeriodsMap[wcId].push({
  id: oeeNode.id,
  periodStartMs: new Date(oeeNode.periodStartAt).getTime(),
  periodEndMs: new Date(oeeNode.periodEndAt).getTime(),
  periodStartAt: oeeNode.periodStartAt,
  periodEndAt: oeeNode.periodEndAt,
  scheduleId: oeeNode.scheduleId,
  scheduleName: oeeNode.schedule ? oeeNode.schedule.name : 'Unscheduled',
  shift: oeeNode.shift || null,
  shiftHour: oeeNode.shiftHour || 0,  // <-- ADD THIS LINE
  isException: (oeeNode.shift === 'exception'),
  exists: true
});
}

for (var wcKey in oeePeriodsMap) {
  oeePeriodsMap[wcKey].sort(function(a, b) {
    return a.periodStartMs - b.periodStartMs;
  });
}

// ========================================
// STEP 2: Group production logs by workcenter
// ========================================
var productionByWorkcenter = {};

for (var p = 0; p < productionEdges.length; p++) {
  var pNode = productionEdges[p].node;
  var wcId = pNode.workcenterId;
  
  if (!productionByWorkcenter[wcId]) {
    productionByWorkcenter[wcId] = [];
  }
  
  var occurAtMs = new Date(pNode.occurAt).getTime();
  var cycleTime = pNode.product?.standardCycleTime || 30;
  var goodQty = pNode.quantityGood || 0;
  var scrapQty = pNode.quantityScrap || 0;
  
  productionByWorkcenter[wcId].push({
    occurAtMs: occurAtMs,
    occurAt: pNode.occurAt,
    quantityGood: goodQty,
    quantityScrap: scrapQty,
    cycleTime: cycleTime,
    productId: pNode.productId,
    scheduleId: pNode.scheduleId
  });
}

// ========================================
// STEP 3: Group history by workcenter
// ========================================
var historyByWorkcenter = {};

for (var h = 0; h < historyEdges.length; h++) {
  var hNode = historyEdges[h].node;
  var hWcId = hNode.workcenterId;
  
  if (!historyByWorkcenter[hWcId]) {
    historyByWorkcenter[hWcId] = [];
  }
  
  var occurAtMs = new Date(hNode.occurAt).getTime();
  var endAtMs = hNode.endAt ? new Date(hNode.endAt).getTime() : hourEndMs;
  
  historyByWorkcenter[hWcId].push({
    occurAtMs: occurAtMs,
    endAtMs: endAtMs,
    occurAt: hNode.occurAt,
    endAt: hNode.endAt,
    mode: hNode.mode,
    state: hNode.state,
    modeId: hNode.modeId,
    scheduleId: hNode.scheduleId,
    scheduleName: hNode.schedule ? hNode.schedule.name : null
  });
}

// ========================================
// STEP 4: Helper to check if period has data
// ========================================
function periodHasData(wcId, periodStartMs, periodEndMs, prodLogs, histRecords) {
  // Check production logs
  for (var pl = 0; pl < prodLogs.length; pl++) {
    if (prodLogs[pl].occurAtMs >= periodStartMs && prodLogs[pl].occurAtMs < periodEndMs) {
      return true;
    }
  }
  
  // Check history records
  for (var hr = 0; hr < histRecords.length; hr++) {
    var hist = histRecords[hr];
    var overlapMs = calcOverlapMs(
      hist.occurAtMs,
      hist.endAtMs,
      periodStartMs,
      periodEndMs
    );
    if (overlapMs > 0) {
      return true;
    }
  }
  
  return false;
}

// ========================================
// STEP 5: Calculate OEE for each period
// ========================================
var payload = [];

var allWorkcenterIds = {};
for (var k1 in oeePeriodsMap) { allWorkcenterIds[k1] = true; }

for (var wcId in allWorkcenterIds) {
  var periods = oeePeriodsMap[wcId] || [];
  var prodLogs = productionByWorkcenter[wcId] || [];
  var histRecords = historyByWorkcenter[wcId] || [];
  
  if (periods.length === 0) {
    console.log('No OEE periods defined for workcenter:', wcId);
    continue;
  }
  
  for (var pi = 0; pi < periods.length; pi++) {
    var period = periods[pi];
    var periodStartMs = period.periodStartMs;
    var periodEndMs = period.periodEndMs;
    var periodDurationMs = periodEndMs - periodStartMs;
    
    // ========================================
    // EXCECustomer-DON HANDLING:
    // Skip exceptions that have no data
    // ========================================
    if (period.isException) {
      var hasData = periodHasData(wcId, periodStartMs, periodEndMs, prodLogs, histRecords);
      if (!hasData) {
        console.log('Skipping exception period with no data:', wcId, period.periodStartAt);
        continue; // Skip this period entirely
      }
    }
    
    // ========================================
    // ALLOCATE PRODUCTION DATA TO THIS PERIOD
    // ========================================
    var periodProduction = {
      goodCount: 0,
      scrapCount: 0,
      totalCount: 0,
      weightedCycleTimeSum: 0
    };
    
    for (var pl = 0; pl < prodLogs.length; pl++) {
      var log = prodLogs[pl];
      
      if (log.occurAtMs >= periodStartMs && log.occurAtMs < periodEndMs) {
        periodProduction.goodCount += log.quantityGood;
        periodProduction.scrapCount += log.quantityScrap;
        var totalQty = log.quantityGood + log.quantityScrap;
        periodProduction.totalCount += totalQty;
        periodProduction.weightedCycleTimeSum += totalQty * log.cycleTime;
      }
    }
    
    // ========================================
    // ALLOCATE HISTORY DATA TO THIS PERIOD
    // ========================================
    var periodTime = {
      runTimeMs: 0,
      plannedDowntimeMs: 0,
      unplannedDowntimeMs: 0,
      setupMs: 0,
      topDowntimeMs: 0,
      accountedMs: 0
    };
    
    for (var hr = 0; hr < histRecords.length; hr++) {
      var hist = histRecords[hr];
      
      var overlapMs = calcOverlapMs(
        hist.occurAtMs,
        hist.endAtMs,
        periodStartMs,
        periodEndMs
      );
      
      if (overlapMs <= 0) continue;
      
      periodTime.accountedMs += overlapMs;
      
      var mode = hist.mode;
      var state = hist.state;
      
      if (state && state.isProducing === true) {
        periodTime.runTimeMs += overlapMs;
      }
      else if (mode && mode.countAsPlannedDowntime === true) {
        periodTime.plannedDowntimeMs += overlapMs;
      }
      else {
        periodTime.unplannedDowntimeMs += overlapMs;
        if (overlapMs > periodTime.topDowntimeMs) {
          periodTime.topDowntimeMs = overlapMs;
        }
      }
      
      if (hist.modeId === 'setup' || (mode && mode.oeeImpact === 'setup')) {
        periodTime.setupMs += overlapMs;
      }
    }
    
    // ========================================
    // HANDLE UNACCOUNTED TIME
    // If no history data at all, set to unplanned downtime
    // ========================================
    var unaccountedMs = periodDurationMs - periodTime.accountedMs;
    if (unaccountedMs > 0) {
      periodTime.unplannedDowntimeMs += unaccountedMs;
      periodTime.accountedMs = periodDurationMs;
    }
    
    // ========================================
    // CALCULATE OEE METRICS (ISO 22400)
    // ========================================
    var plannedProductionTimeMs = periodDurationMs - periodTime.plannedDowntimeMs;
    
    var idealCycleTime = periodProduction.totalCount > 0
      ? periodProduction.weightedCycleTimeSum / periodProduction.totalCount
      : 30;
    
    var actualCycleTime = periodProduction.totalCount > 0
      ? (periodTime.runTimeMs / 1000) / periodProduction.totalCount
      : 0;
    
    var idealCount = (periodTime.runTimeMs > 0 && idealCycleTime > 0)
      ? (periodTime.runTimeMs / 1000) / idealCycleTime
      : 0;
    
    // Availability = Operating Time / Planned Production Time
    var availability = plannedProductionTimeMs > 0
      ? Math.min(periodTime.runTimeMs / plannedProductionTimeMs, 1)
      : 0;
    
    // Performance = Actual Output / Ideal Output
    var performance = idealCount > 0
      ? Math.min(periodProduction.totalCount / idealCount, 1)
      : 0;
    
    // Quality = Good Units / Total Units
    var quality = periodProduction.totalCount > 0
      ? periodProduction.goodCount / periodProduction.totalCount
      : 1;
    
    // OEE = A × P × Q
    var oee = availability * performance * quality;
    
    // Shift hour calculation (placeholder - needs schedule.shiftStartAt)
  var shiftHour = period.shiftHour || 0;
    
    // ========================================
    // BUILD PAYLOAD WITH BOTH CREATE AND UPDATE
    // ========================================
    var recordId = period.id || (wcId + '-' + period.periodStartAt);
    
    payload.push({
      "where": {
        "id": recordId
      },
      "create": {
        "id": recordId,
        "workcenterId": wcId,
        "periodStartAt": period.periodStartAt,
        "periodEndAt": period.periodEndAt,
        "dayHour": dayHour,
        "shiftHour": shiftHour,
        "shift": period.shift || period.scheduleName,
        "scheduleId": period.scheduleId,
        "plannedMinutes": plannedProductionTimeMs,
        "runMinutes": periodTime.runTimeMs,
        "downtimeMinutes": periodTime.unplannedDowntimeMs,
        "plannedDowntimeMinutes": periodTime.plannedDowntimeMs,
        "setupMinutes": periodTime.setupMs,
        "topDowntime": periodTime.topDowntimeMs,
        "idealCycleTime": Math.round(idealCycleTime * 1000),
        "actualCycleTime": Math.round(actualCycleTime * 1000),
        "goodUnits": periodProduction.goodCount,
        "scrapUnits": periodProduction.scrapCount,
        "totalUnits": periodProduction.totalCount,
        "idealUnits": Math.round(idealCount * 100) / 100,
        "availability": Math.round(availability * 10000) / 10000,
        "performance": Math.round(performance * 10000) / 10000,
        "quality": Math.round(quality * 10000) / 10000,
        "oee": Math.round(oee * 10000) / 10000
      },
      "update": {
        "shift": period.shift || period.scheduleName,
        "scheduleId": period.scheduleId,
        "dayHour": dayHour,
        "shiftHour": shiftHour,
        "plannedMinutes": plannedProductionTimeMs,
        "runMinutes": periodTime.runTimeMs,
        "downtimeMinutes": periodTime.unplannedDowntimeMs,
        "plannedDowntimeMinutes": periodTime.plannedDowntimeMs,
        "setupMinutes": periodTime.setupMs,
        "topDowntime": periodTime.topDowntimeMs,
        "idealCycleTime": Math.round(idealCycleTime * 1000),
        "actualCycleTime": Math.round(actualCycleTime * 1000),
        "goodUnits": periodProduction.goodCount,
        "scrapUnits": periodProduction.scrapCount,
        "totalUnits": periodProduction.totalCount,
        "idealUnits": Math.round(idealCount * 100) / 100,
        "availability": Math.round(availability * 10000) / 10000,
        "performance": Math.round(performance * 10000) / 10000,
        "quality": Math.round(quality * 10000) / 10000,
        "oee": Math.round(oee * 10000) / 10000
      }
    });
  }
}

console.log('OEE payload:', payload.length, 'periods processed');

return { "payload": payload };

data.mutation:
mutation UpsertOeeHourly($payload: [OeeHourlyUpsertPayloadInput!]!) {
  upsertOeeHourly(payload: $payload) {
    id
    workcenterId
    oee
    availability
    performance
    quality
  }
}

data.query:
query OeeDataForHour(
  $productionWhere: ProductionLogWhereInput
  $historyWhere: WorkcenterHistoryWhereInput
  $oeeHourlyWhere: OeeHourlyWhereInput
) {
  productionLog(where: $productionWhere, first: 100000) {
    edges {
      node {
        id
        workcenterId
        occurAt
        productId
        scheduleId
        product {
          standardCycleTime
          targetYield
        }
        quantityGood
        quantityScrap
        cycleTime
      }
    }
  }
  
  workcenterHistory(where: $historyWhere, first: 100000) {
    edges {
      node {
        id
        workcenterId
        modeId
        stateId
        scheduleId
        occurAt
        endAt
        mode {
          countAsDowntime
          countAsProductionTime
          countAsPlannedDowntime
          oeeImpact
        }
        state {
          isProducing
          isPerformanceLoss
          isFault
        }
        schedule {
          id
          name
        }
      }
    }
  }
  
  oeeHourly(where: $oeeHourlyWhere, first: 100000) {
    edges {
      node {
        id
        workcenterId
        periodStartAt
        periodEndAt
        shift
        shiftHour
        scheduleId
        schedule {
          id
          name
        }
      }
    }
  }
}

