data.query:
query OeeDataForHour(
  $productionWhere: ProductionLogWhereInput
  $historyWhere: WorkcenterHistoryWhereInput
  $oeeHourlyWhere: OeeHourlyWhereInput
) {
  productionLog(where: $productionWhere, first: 100000) {
    edges {
      node {
        id
        workcenterId
        occurAt
        productId
        scheduleId
        product {
          standardCycleTime
          targetYield
        }
        quantityGood
        quantityScrap
        cycleTime
      }
    }
  }
  
  workcenterHistory(where: $historyWhere, first: 100000) {
    edges {
      node {
        id
        workcenterId
        modeId
        stateId
        scheduleId
        occurAt
        endAt
        mode {
          countAsDowntime
          countAsProductionTime
          countAsPlannedDowntime
          oeeImpact
        }
        state {
          isProducing
          isPerformanceLoss
          isFault
        }
        schedule {
          id
          name
        }
      }
    }
  }
  
  oeeHourly(where: $oeeHourlyWhere, first: 100000) {
    edges {
      node {
        id
        workcenterId
        periodStartAt
        periodEndAt
        shift
        shiftHour
        scheduleId
        schedule {
          id
          name
        }
      }
    }
  }
}

