'use strict';

// Extract timezone from query result
const settingEdges = $.setting?.edges || [];
let timezone = null;

if (settingEdges.length > 0 && settingEdges[0].node?.defaultValue) {
  timezone = settingEdges[0].node.defaultValue;
  console.log('Using configured timezone: ' + timezone);
} else {
  timezone = $momentTzGuess();
  console.log('No timezone configured, using guess: ' + timezone);
}

// Extract workcenters
const workcenters = $.workcenter?.edges?.map(e => e.node) || [];

console.log('Found ' + workcenters.length + ' active workcenters with schedules');

// Calculate today's boundaries in local timezone
const now = $moment().tz(timezone);
const todayStart = now.clone().startOf('day');
const todayEnd = now.clone();

// Calculate yesterday's boundaries
const yesterdayStart = now.clone().subtract(1, 'day').startOf('day');
const yesterdayEnd = now.clone().subtract(1, 'day').endOf('day');

// Determine if we should calculate yesterday (first 5 minutes of new day)
const minutesIntoDay = now.diff(todayStart, 'minutes');
const shouldCalculateYesterday = minutesIntoDay < 20;

console.log('═══════════════════════════════════════════════════════════');
console.log('OEE Daily Real-time Aggregation - Boundaries Calculated');
console.log('═══════════════════════════════════════════════════════════');
console.log('Timezone: ' + timezone);
console.log('Current Time (local): ' + now.format('YYYY-MM-DD HH:mm:ss'));
console.log('Minutes into day: ' + minutesIntoDay);
console.log('Should calculate yesterday: ' + shouldCalculateYesterday);
console.log('---');
console.log('TODAY:');
console.log('  Date: ' + todayStart.format('YYYY-MM-DD'));
console.log('  Period (local): ' + todayStart.format('YYYY-MM-DD HH:mm:ss') + ' to ' + todayEnd.format('YYYY-MM-DD HH:mm:ss'));

if (shouldCalculateYesterday) {
  console.log('---');
  console.log('YESTERDAY (final calculation):');
  console.log('  Date: ' + yesterdayStart.format('YYYY-MM-DD'));
  console.log('  Period (local): ' + yesterdayStart.format('YYYY-MM-DD HH:mm:ss') + ' to ' + yesterdayEnd.format('YYYY-MM-DD HH:mm:ss'));
}
console.log('═══════════════════════════════════════════════════════════');

// Build array of periods to calculate
const periods = [
  {
    name: 'today',
    date: todayStart.format('YYYY-MM-DD'),
    startLocal: todayStart.toISOString(),
    endLocal: todayEnd.toISOString(),
    startUTC: todayStart.clone().utc().toISOString(),
    endUTC: todayEnd.clone().utc().toISOString()
  }
];

// Add yesterday if within grace period
if (shouldCalculateYesterday) {
  periods.push({
    name: 'yesterday',
    date: yesterdayStart.format('YYYY-MM-DD'),
    startLocal: yesterdayStart.toISOString(),
    endLocal: yesterdayEnd.toISOString(),
    startUTC: yesterdayStart.clone().utc().toISOString(),
    endUTC: yesterdayEnd.clone().utc().toISOString()
  });
}

// Return data for context
return {
  timezone: timezone,
  workcenters: workcenters,
  workcenterCount: workcenters.length,
  periods: periods,
  shouldCalculateYesterday: shouldCalculateYesterday
};

data.query:
query GetWorkcenterData(
  $workcenterId: String!
  $todayStart: DateTime!
  $todayEnd: DateTime!
) {
  # Return the period identifiers for tracking
  _meta: __type(name: "Query") {
    name
    
  }
  
  # Get workcenter details for code
  workcenter(where: { id: { _eq: $workcenterId } }) {
    edges {
      node {
        id
        code
        name
      }
    }
  }
  
  # Get all WorkcenterHistory for this workcenter that overlaps with period
  workcenterHistory(
    where: {
      workcenterId: { _eq: $workcenterId }
      _and: [
        {
          occurAt: { _lt: $todayEnd }
        }
        {
          _or: [
            { endAt: { _gte: $todayStart } }
            { endAt: { _isNull: true } }
          ]
        }
      ]
    }
    first: 10000
    orderBy: { field: occurAt, direction: asc }
  ) {
    edges {
      node {
        id
        workcenterId
        occurAt
        endAt
        duration(format: milliseconds)
        scheduleId
        modeId
        mode {
          id
          name
          countAsProductionTime
          countAsDowntime
          countAsPlannedDowntime
        }
      }
    }
  }
  
  # Get ProductionLog for this workcenter created during period
  productionLog(
    where: {
      workcenterId: { _eq: $workcenterId }
      occurAt: { _gte: $todayStart, _lte: $todayEnd }
    }
    first: 10000
    orderBy: { field: occurAt, direction: asc }
  ) {
    edges {
      node {
        id
        workcenterId
        occurAt
        quantityGood
        quantityScrap
        cycleTime
        productId
        product {
          standardCycleTime
          idealCycleTime(format: milliseconds)
        }
      }
    }
  }
}

