)

data.query:
query GetProductionWorkcentersAndActiveWorkOrders($now: DateTime!) {
  # Get workcenters currently in production mode
  workcenterHistory(
    where: {
      endAt: { _isNull: true }
      workcenterId: { _isNull: false }
      modeId: { _eq: "production" }
    }
    first: 10000
  ) {
    edges {
      node {
        id
        workcenterId
        modeId
        occurAt
        scheduleId
        mode {
          countAsDowntime
          countAsProductionTime
          countAsPlannedDowntime
        }
        state{
            
                code
        isProducing
        isPerformanceLoss
        isFault
        }
      }
    }
  }
  
  # Get all active work orders
  workOrder(
    where: {
      status: { _in: ["Released", "InProgress"] }
      scheduledStartAt: { _lte: $now }
    }
    first: 1000
  ) {
    edges {
      node {
        id
        code
        status
        quantityTarget
        quantityCompleted
        productionLogs{
          total
           edges {
            node{
              createdAt
              quantityGood
              quantityScrap
              occurAt
            }

           }
        }
        quantityScrap
        scheduledStartAt
        scheduledEndAt
        productId
        workcenterId
        product {
          id
          code
          standardCycleTime
          idealCycleTime (format: milliseconds)
          targetYield
        }
        workcenter {
          id
          code
          name
          scheduleGroupId
        }
      }
    }
  }
  
  # Get timezone setting
  setting(where: { id: { _eq: "TimeZone" } }) {
    edges {
      node {
        id
        defaultValue
      }
    }
  }
}

