query GetDataPointsByType {
  floatDataPoints: dataPoint(
    where: {
      historize: { _eq: true }
      enabled: { _eq: true }
      dataType: { _eq: "float" }
      asset: { status: { _eq: "Active" } }
    }
    first: 10000
  ) {
    edges {
      node {
        id
        dataType
        frequency
        setPoint
        upperLimit
        lowerLimit
        tolerance
        precision
      }
    }
  }
  
  integerDataPoints: dataPoint(
