    }
    first: 10000
  ) {
    edges {
      node {
        id
        frequency
        setPoint
        upperLimit
        lowerLimit
        tolerance
        precision
      }
    }
  }
  
  booleanDataPoints: dataPoint(
    where: {
      historize: { _eq: true }
      enabled: { _eq: true }
      dataType: { _eq: "boolean" }
      asset: { status: { _eq: "Active" } }
    }
    first: 10000
  ) {
    edges {
      node {
        id
