'use strict';

// ============================================================================
// ISO 22400-COMPLIANT WORKCENTER STATE CHANGE GENERATOR
// ============================================================================
// Generates realistic workcenter state transitions for manufacturing simulation
// Strictly adheres to ISO 22400-2 standards for proper OEE classification
//
// Key Principles:
// - Production mode = Equipment ACTIVELY PRODUCING (runTime)
// - Planned downtime = SCHEDULED STOPS (maintenance, breaks, etc.)
// - Unplanned downtime = UNSCHEDULED STOPS (faults, breakdowns, etc.)
// - Blocked/Starved/Faulted = Always DOWNTIME, never production
// - Maintenance/No-Schedule = OUTSIDE production time (excluded from OEE)
//
// Time Classification Fields (ISO 22400):
// - duration: Total duration in milliseconds
// - runTime: milliseconds in production mode (countAsProductionTime = true)
// - plannedDowntime: milliseconds in planned downtime (countAsDowntime & countAsPlannedDowntime)
// - unplannedDowntime: milliseconds in unplanned downtime (countAsDowntime & !countAsPlannedDowntime)
//
// Output Structure:
// Returns up to 2 batches:
// - One close batch (if any records need closing)
// - One combined create+update batch (if any state changes occur)
// ============================================================================

// Extract tenant timezone from settings
var settingEdges = ($ && $.setting && $.setting.edges) || [];
var timezone = ($ && $.tenantTimezone) || 
               (settingEdges.length > 0 && settingEdges[0].node && settingEdges[0].node.defaultValue) || 
               'UTC';

// Current execution timestamp in tenant local time, represented as UTC
var nowMoment = $moment().tz(timezone);
var nowUTCTs = nowMoment.utc().toISOString();
var nowUTCMs = nowMoment.valueOf();

// ============================================================================
// CONFIGURATION PARAMETERS
// ============================================================================
var changeProb = 0.30;            // Probability of state change (30%)
var minProductionRatio = 0.40;    // Minimum 40% in production mode

// ============================================================================
// EXTRACT REFERENCE DATA WITH NULL SAFETY
// ============================================================================
var workcenters = ($ && $.workcenter && $.workcenter.edges) 
  ? $.workcenter.edges.map(function(e) { return e.node; }) 
  : [];

var events = ($ && $.event && $.event.edges)
  ? $.event.edges.map(function(e) { return e.node; })
  : [];

var modes = ($ && $.mode && $.mode.edges)
  ? $.mode.edges.map(function(e) { return e.node; })
  : [];

var states = ($ && $.state && $.state.edges)
  ? $.state.edges.map(function(e) { return e.node; })
  : [];

var currentScheduleByGroup = ($ && $.currentScheduleByGroup) || {};

// ============================================================================
// BUILD OPEN HISTORY LOOKUP - DETECT DUPLICATES
// ============================================================================
var openHistoryByWc = {};
var duplicateOpenHistory = [];

($.workcenterHistory && $.workcenterHistory.edges ? $.workcenterHistory.edges : []).forEach(function(e) {
  var wcId = e.node.workcenterId;
  
  if (!openHistoryByWc[wcId]) {
    openHistoryByWc[wcId] = e.node;
  } else {
    var existing = openHistoryByWc[wcId];
    var existingMs = $moment(existing.occurAt).valueOf();
    var newMs = $moment(e.node.occurAt).valueOf();
    
    if (newMs > existingMs) {
      duplicateOpenHistory.push(existing);
      openHistoryByWc[wcId] = e.node;
    } else {
      duplicateOpenHistory.push(e.node);
    }
  }
});

if (duplicateOpenHistory.length > 0) {
  console.log('WARNING: Found ' + duplicateOpenHistory.length + ' duplicate open history records. Will close them.');
}

// ============================================================================
// BUILD MODE AND STATE LOOKUPS
// ============================================================================
var modeById = {};
modes.forEach(function(m) { modeById[m.id] = m; });

var stateById = {};
states.forEach(function(s) { stateById[s.id] = s; });

// Required modes and states
var noScheduleMode = modeById['no-schedule'];
var offlineState = stateById['offline'];

// Validate required reference data exists
if (!noScheduleMode) {
  console.error('ERROR: no-schedule mode not found - required for unscheduled workcenters');
}
if (!offlineState) {
  console.error('ERROR: offline state not found - required for default state');
}

// Fallback to first available if required data missing
if (!noScheduleMode && modes.length > 0) {
  noScheduleMode = modes[0];
  console.warn('Using fallback mode: ' + noScheduleMode.id);
}
if (!offlineState && states.length > 0) {
  offlineState = states[0];
  console.warn('Using fallback state: ' + offlineState.id);
}

// Critical validation - cannot proceed without modes and states
if (modes.length === 0 || states.length === 0) {
  console.error('CRITICAL ERROR: No modes or states found in system. Cannot proceed.');
  return null;
}

// ============================================================================
// ISO 22400-2 COMPLIANT MODE-STATE TRANSITIONS
// ============================================================================
var validStatesByMode = {
  'production': ['running', 'running-slow', 'unknown'],
  'disabled': ['faulted', 'e-stopped', 'blocked', 'starved', 'offline'],
  'setup': ['changeover', 'warmup', 'cleaning'],
  'cleaning': ['cleaning', 'offline'],
  'idle': ['stopped', 'offline'],
  'maintenance': ['maintenance', 'offline'],
  'no-schedule': ['offline'],
  'engineering': ['stopped', 'offline', 'changeover']
};

var defaultStateByMode = {
  'production': 'running',
  'disabled': 'faulted',
  'setup': 'changeover',
  'cleaning': 'cleaning',
  'idle': 'stopped',
  'maintenance': 'maintenance',
  'no-schedule': 'offline',
  'engineering': 'stopped'
};

// ============================================================================
// HELPER FUNCTIONS
// ============================================================================

function getValidStatesForMode(modeId) {
  var validStateIds = validStatesByMode[modeId] || [];
  return validStateIds.map(function(sid) { return stateById[sid]; }).filter(function(s) { return s; });
}

function selectValidStateForMode(mode) {
  if (!mode) return states[0];
  
  var validStates = getValidStatesForMode(mode.id);
  
  if (validStates.length === 0) {
    var defaultSid = defaultStateByMode[mode.id];
    return stateById[defaultSid] || states[0];
  }
  
  if (mode.id === 'production') {
    var producingStates = validStates.filter(function(s) { return s.isProducing; });
    if (producingStates.length > 0 && Math.random() < 0.85) {
      return producingStates[Math.floor(Math.random() * producingStates.length)];
    }
  }
  
  return validStates[Math.floor(Math.random() * validStates.length)];
}

function shouldChangeState(openHistory, nowMs) {
  if (!openHistory) return true;
  
  var openMoment = $moment(openHistory.occurAt);
  var elapsedMs = nowMs - openMoment.valueOf();
