  /* Process each scheduleGroupId and create batches of 25 */
  $keys($grouped).(
    $scheduleGroupId := $;
    $allIds := $lookup($grouped, $);
    $totalCount := $count($allIds);
    
    /* Create batches using array filtering */
    [$map([0..$ceil($totalCount / 25) - 1], function($batchNum) {
      {
        "workcenterIds": $filter($allIds, function($v, $i) {
          $i >= $batchNum * 25 and $i < ($batchNum + 1) * 25
        }),
        "config": $merge([$config, {"scheduleGroupId": $scheduleGroupId}])
      }
    })]
  )[]
)

