data.transform:
// ============================================
// Alarm Evaluation & Payload Generation
// ============================================

// Inputs
const telemetry = $state.context.rawData.value.after;  // Full telemetry record from subscription
const dpData = $.dataPoint.edges[0]?.node;
const activeAlarms = $.activeAlarms?.edges?.map(e => e.node) || [];

// 1. Validate DataPoint exists
if (!dpData) {
  return {
    skip: true,
    reason: `DataPoint ${telemetry.dataPointId} not found in query results`
  };
}

// 2. Check if alarmEnabled
if (!dpData.alarmEnabled) {
  return {
    skip: true,
    reason: `Alarms disabled for DataPoint ${dpData.code}`
  };
}

// 3. Extract critical values
const value = telemetry.value;
const qualityCode = telemetry.qualityCode;
const deadband = dpData.deadband || 0;

// 4. Check active alarms - if exists, evaluate deadband from previous trigger
if (activeAlarms.length > 0) {
  const latestAlarm = activeAlarms[0]; // Already sorted desc by triggeredAt
  const previousValue = latestAlarm.triggerValue;
  const valueDelta = Math.abs(value - previousValue);
  
  // If change is within deadband, skip creating new alarm
  if (valueDelta <= deadband) {
    return {
      skip: true,
      reason: `Value change (${valueDelta.toFixed(2)}) within deadband (${deadband}) of active alarm ${latestAlarm.code}`,
      activeAlarmId: latestAlarm.id,
      activeAlarmCode: latestAlarm.code,
      previousValue: previousValue,
      newValue: value,
      delta: valueDelta
    };
  }
}

// 5. Determine alarm condition with deadband checking
let limitType = null;
let limitValue = null;
let deviation = null;

// Quality is already BAD (16) or UNCERTAIN (64) per Accept node
// Now determine WHY it's bad - which limit was violated?

// Priority 1: Check critical limits (alarms)
if (dpData.upperLimit != null && value > (dpData.upperLimit + deadband)) {
  limitType = 'HighLimit';
  limitValue = dpData.upperLimit;
  deviation = value - dpData.upperLimit;
}
else if (dpData.lowerLimit != null && value < (dpData.lowerLimit - deadband)) {
  limitType = 'LowLimit';
  limitValue = dpData.lowerLimit;
  deviation = dpData.lowerLimit - value;
}
// Priority 2: Check warning limits
else if (dpData.upperWarning != null && value > (dpData.upperWarning + deadband)) {
  limitType = 'HighWarning';
  limitValue = dpData.upperWarning;
  deviation = value - dpData.upperWarning;
}
else if (dpData.lowerWarning != null && value < (dpData.lowerWarning - deadband)) {
  limitType = 'LowWarning';
  limitValue = dpData.lowerWarning;
  deviation = dpData.lowerWarning - value;
}
// Priority 3: Check setPoint tolerance deviation
else if (dpData.setPoint != null && dpData.tolerance != null) {
  const setPointDeviation = Math.abs(value - dpData.setPoint);
  if (setPointDeviation > (dpData.tolerance + deadband)) {
    limitType = 'Deviation';
    limitValue = dpData.setPoint;
    deviation = setPointDeviation;
  }
}

// No limit violation found
if (!limitType) {
  return {
    skip: true,
    reason: `Value ${value} within all limits for ${dpData.code}`
  };
}

// 6. Build Alarm creation payload
return {
  dataPointId: dpData.id,
  limitType: limitType,
  limitValue: limitValue,
  triggerValue: value,
  deviation: deviation,
  triggeredAt: telemetry.recordedAt || new Date().toISOString(),
  alarmStateId: 'ACTIVE',
  notes: `${limitType} alarm triggered for ${dpData.displayName} (${dpData.code})`,
  customFields: {
    telemetrySnapshot: telemetry,
    assetCode: dpData.asset?.code,
    assetId: dpData.asset?.id,
    unitCode: dpData.unit?.code,
    dataPointCode: dpData.code,
    dataPointName: dpData.displayName,
    category: dpData.category,
    qualityCode: qualityCode,
    isCritical: dpData.isCritical,
    alarmPriority: dpData.alarmPriority
  }
};

