'use strict';

// Input: Data change capture from subscription
// Structure: { value: { before: {}, after: {} }, topic: "", headers: {} }

// Extract the after state from the data change event
const history = $.value.after;

// Validate this is an update with endAt being set
const before = $.value.before;

if (!before || !history) {
  throw new Error('Missing before/after data in subscription payload');
}

// Only process when endAt is being set (was null, now has value)
if (before.endAt !== null && before.endAt !== undefined) {
  console.log(`Skipping: WorkcenterHistory ${history.id} - endAt was already set`);
  return null;
}

if (!history.endAt) {
  console.log(`Skipping: WorkcenterHistory ${history.id} - endAt still null`);
  return null;
}

// Validate required fields exist
if (!history.occurAt || !history.workcenterId) {
  throw new Error(`Missing required fields in WorkcenterHistory ${history.id}`);
}

// Calculate duration in milliseconds and minutes
const historyStart = new Date(history.occurAt);
const historyEnd = new Date(history.endAt);
const durationMs = historyEnd - historyStart;

// Validate duration is positive
if (durationMs <= 0) {
  throw new Error(
    `Invalid duration for WorkcenterHistory ${history.id}: ` +
    `endAt (${history.endAt}) must be after occurAt (${history.occurAt})`
  );
}

const durationMinutes = durationMs / (1000 * 60);

console.log(
  `Processing WorkcenterHistory ${history.id}: ` +
  `${durationMinutes.toFixed(2)} minutes (${history.occurAt} to ${history.endAt})`
);

// Prepare output for next step
return {
  workcenterId: history.workcenterId,
  historyId: history.id,
  historyStart: history.occurAt,
  historyEnd: history.endAt,
  durationMs: durationMs,
  durationMinutes: durationMinutes,
  modeId: history.modeId,
  stateId: history.stateId,
  scheduleId: history.scheduleId
};

data.query:
query GetModeAndAffectedHours(
  $modeId: String!
  $workcenterId: String!
  $historyStart: DateTime!
  $historyEnd: DateTime!
) {
  mode(where: { id: { _eq: $modeId } }) {
    edges {
      node {
        id
        code
        name
        countAsProductionTime
        countAsDowntime
        countAsPlannedDowntime
        oeeImpact
      }
    }
  }
  
  oeeHourly(
    where: {
      _and: [
        { workcenterId: { _eq: $workcenterId } }
        { scheduleHourStartAt: { _lt: $historyEnd } }
        { scheduleHourEndAt: { _gt: $historyStart } }
      ]
    }
    orderBy: { field: scheduleHourStartAt, direction: asc  }
  ) {
    edges {
      node {
        id
        workcenterId
        periodStartAt
        periodEndAt
        scheduleHourStartAt
        scheduleHourEndAt
        runMinutes(format:  milliseconds)
        setupMinutes(format: milliseconds)
        downtimeMinutes(format: milliseconds)
        idealCycleTime(format: milliseconds)
        plannedDowntimeMinutes(format: milliseconds)
        plannedMinutes(format: milliseconds)
        scheduledTime(format: milliseconds)
        modeChanges
        stateChanges
        scheduleId
      }
    }
  }
}

data.transform:
'use strict';

// ═══════════════════════════════════════════════════════════════════════
// ISO 22400-COMPLIANT OEE HOURLY AGGREGATION
// ═══════════════════════════════════════════════════════════════════════
// Processes WorkcenterHistory events and updates OeeHourly records
// - Validates data integrity (prevents exceeding hour duration)
// - Handles NO-SCHEDULE mode with scheduleId validation
// - Classifies time according to mode (run/setup/downtime/planned downtime)
// - Calculates ISO 22400 availability percentage
// - Returns pure milliseconds (no ISO duration strings)
// ═══════════════════════════════════════════════════════════════════════

// Extract mode and hours from combined GraphQL response
const mode = $.mode?.edges?.[0]?.node;
const hours = $.oeeHourly?.edges?.map(edge => edge.node) || [];

// Restore context data
const historyStart = new Date($state.context.historyStart);
const historyEnd = new Date($state.context.historyEnd);

// Validate mode exists
if (!mode) {
  console.error(`Mode ${$state.context.modeId} not found - skipping history ${$state.context.historyId}`);
  return { skip: true, reason: 'mode_not_found' };
}

// Validate hours found
if (hours.length === 0) {
  console.log(`No OeeHourly records found for workcenter ${$state.context.workcenterId} - no updates needed`);
  return { skip: true, reason: 'no_hourly_records_found' };
}

console.log(`Processing mode ${mode.code} (${mode.name}) affecting ${hours.length} hours`);

// ═══════════════════════════════════════════════════════════════════════
// CRITICAL HELPER: Extract pure milliseconds from any duration format
// Handles edge case where GraphQL returns strings even with (format: milliseconds)
// ═══════════════════════════════════════════════════════════════════════
function extractMilliseconds(duration) {
  // Null/undefined check
  if (!duration && duration !== 0) return 0;
  
  // Already a number - return as-is
  if (typeof duration === 'number') {
    return Math.floor(duration);
  }
  
  // Duration object with milliseconds property
  if (typeof duration === 'object' && duration !== null && duration.milliseconds !== undefined) {
    return Math.floor(duration.milliseconds);
  }
  
  // String - could be ISO duration or numeric string
  if (typeof duration === 'string') {
    // Check if it's an ISO duration string (starts with PT)
    if (duration.startsWith('PT')) {
      try {
        const ms = $momentDuration(duration).asMilliseconds();
        return Math.floor(ms);
      } catch (e) {
        console.warn('Failed to parse ISO duration string: "' + duration + '", error: ' + e.message);
        return 0;
      }
    }
    
    // Check if it's a numeric string (e.g., "3600000")
    const parsed = parseFloat(duration);
    if (!isNaN(parsed)) {
      return Math.floor(parsed);
    }
    
    console.warn('Unknown string duration format: "' + duration + '"');
    return 0;
  }
  
  // Unknown type
  console.warn('Unknown duration type: ' + typeof duration + ', value: ' + JSON.stringify(duration));
  return 0;
}

// ═══════════════════════════════════════════════════════════════════════
// BUILD UPDATE PAYLOADS
// ═══════════════════════════════════════════════════════════════════════
const payload = hours.map(hour => {
  const scheduleStart = new Date(hour.scheduleHourStartAt);
  const scheduleEnd = new Date(hour.scheduleHourEndAt);
  
  // Calculate the TOTAL duration of this OEE hour (the absolute maximum)
  const hourTotalDurationMs = scheduleEnd - scheduleStart;
  
  if (hourTotalDurationMs <= 0) {
    console.error(`Invalid hour duration for ${hour.id}: scheduleHourEndAt must be after scheduleHourStartAt`);
    return null;
  }
  
  // Calculate overlap between history and schedule hour
  const overlapStart = historyStart > scheduleStart ? historyStart : scheduleStart;
  const overlapEnd = historyEnd < scheduleEnd ? historyEnd : scheduleEnd;
  const overlapMs = overlapEnd - overlapStart;
  
  if (overlapMs <= 0) {
    return null; // No overlap
  }
  
  // ═══════════════════════════════════════════════════════════════════════
  // EXTRACT PURE MILLISECONDS - Handles strings, objects, and numbers
  // ═══════════════════════════════════════════════════════════════════════
  const currentRunMs = extractMilliseconds(hour.runMinutes);
  const currentSetupMs = extractMilliseconds(hour.setupMinutes);
  const currentDowntimeMs = extractMilliseconds(hour.downtimeMinutes);
  const currentPlannedDowntimeMs = extractMilliseconds(hour.plannedDowntimeMinutes);
  const plannedMinutesMs = extractMilliseconds(hour.plannedMinutes);
  const scheduledTimeMs = extractMilliseconds(hour.scheduledTime);
  const currentModeChanges = hour.modeChanges || 0;
  const currentStateChanges = hour.stateChanges || 0;
  
  // Calculate currently accounted time
  const currentTotalAccountedMs = currentRunMs + currentSetupMs + currentDowntimeMs + currentPlannedDowntimeMs;
  
  // ═══════════════════════════════════════════════════════════════════════
  // CRITICAL PRE-FLIGHT CHECK: Validate existing data integrity
  // ═══════════════════════════════════════════════════════════════════════
  if (currentTotalAccountedMs > hourTotalDurationMs) {
    const excessMs = currentTotalAccountedMs - hourTotalDurationMs;
    console.error(
      `DATA INTEGRITY ERROR: Hour ${hour.id} ALREADY EXCEEDS duration! ` +
      `Current total: ${(currentTotalAccountedMs/60000).toFixed(2)}min ` +
      `(Run: ${(currentRunMs/60000).toFixed(2)}, ` +
      `Setup: ${(currentSetupMs/60000).toFixed(2)}, ` +
      `Downtime: ${(currentDowntimeMs/60000).toFixed(2)}, ` +
      `PlannedDT: ${(currentPlannedDowntimeMs/60000).toFixed(2)}) ` +
      `exceeds hour duration ${(hourTotalDurationMs/60000).toFixed(2)}min by ${(excessMs/60000).toFixed(2)}min. ` +
      `REFUSING to add more time.`
    );
    return null;
  }
  
  // Calculate remaining capacity
  const remainingCapacityMs = hourTotalDurationMs - currentTotalAccountedMs;
  
  if (remainingCapacityMs === 0) {
    console.log(`Hour ${hour.id} is 100% accounted - no capacity for additional time`);
    return null;
  }
  
  console.log(
    `Hour ${hour.id} current state: ${(currentTotalAccountedMs/60000).toFixed(2)}/${(hourTotalDurationMs/60000).toFixed(2)}min ` +
    `(${(currentTotalAccountedMs/hourTotalDurationMs*100).toFixed(1)}%), ` +
    `remaining: ${(remainingCapacityMs/60000).toFixed(2)}min`
  );
  
  // ═══════════════════════════════════════════════════════════════════════
  // SPECIAL HANDLING FOR NO-SCHEDULE MODE
  // ═══════════════════════════════════════════════════════════════════════
  let effectiveMode = mode;
  if (mode.code === 'NO-SCHEDULE' || mode.id === 'no-schedule') {
    if (hour.scheduleId) {
      console.warn(
        `Hour ${hour.id} has scheduleId ${hour.scheduleId} but workcenter is in NO-SCHEDULE mode - ` +
        `treating as UNPLANNED DOWNTIME`
      );
      effectiveMode = {
        ...mode,
        countAsProductionTime: true,
