    }
  ]
};

// Fault Count Chart
const faultCountChart = {
  chart: {
    caption: "Weekly Fault Count",
    xAxisName: "Week",
    yAxisName: "Faults",
    theme: "fusion",
    showValues: "1"
  },
  data: weeklyMetrics.map(w => ({
    label: w.weekLabel,
